message.content:
{
  "css": ".trip-footer {
  margin-top: 24px;
}

.trip-footer button[type="button"] {
  display: block;
  width: 100%;
  min-height: 56px;
  padding: 0 16px;
  background-color: #bdbdbd;
  color: #ffffff;
  font-family: "Noto Sans KR", sans-serif;
  font-size: 16px;
  font-weight: 700;
  line-height: 56px;
  text-align: center;
  border-radius: 12px;
  border: none;
  cursor: default;
  opacity: 1;
}

.trip-footer button[type="button"]:disabled {
  background-color: #bdbdbd;
  color: #ffffff;
}"
}
